// Keep review rows only. Company, coverage and error rows have their own rowType.
// In only-new mode every review arrives once; a review edited in the last 7 days comes back with changeType 'edited'.
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (r.rowType !== 'review' || !r.reviewId) continue;
  out.push({
    json: {
      reviewId: r.reviewId,
      date: r.date,
      company: r.productName,
      rating: r.ratingOverall,
      title: r.title ?? '',
      text: r.text ?? '',
      companyReply: r.vendorResponse ?? '',
      verified: r.reviewerVerified === true,
      language: r.language ?? '',
      edited: r.extras?.changeType === 'edited',
      url: r.reviewUrl ?? r.productUrl ?? '',
      scrapedAt: r.scrapedAt,
    },
  });
}
return out;

// One Slack message per run: counts per company and star, then the newest low-star reviews.
// Nothing is posted when the run found no new reviews (this node then gets no items).
const rows = $input.all().map((i) => i.json);
if (rows.length === 0) return [];
const MAX_LISTED = 10;
const byCompany = {};
for (const r of rows) {
  const c = (byCompany[r.company] ??= { total: 0, low: 0 });
  c.total++;
  if (Number(r.rating) <= 2) c.low++;
}
const lines = Object.entries(byCompany).map(
  ([name, c]) => `*${name}*: ${c.total} new review${c.total === 1 ? '' : 's'}, ${c.low} with 1-2 stars`,
);
const low = rows.filter((r) => Number(r.rating) <= 2).slice(0, MAX_LISTED);
for (const r of low) {
  const snippet = `${r.title ? `${r.title} - ` : ''}${r.text}`.slice(0, 300);
  lines.push(`${'★'.repeat(Number(r.rating))} ${r.company} (${r.date})${r.edited ? ' [edited]' : ''}\n>${snippet}\n${r.url}`);
}
return [{ json: { text: `New Trustpilot reviews\n${lines.join('\n')}` } }];
